// Structural tests for the CFG builder. These assert on the generated bytecode directly rather than
// simulating it, so they pin down which CFG instructions were honoured and which were dropped.
#include <gtest/gtest.h>

#include <cstdint>
#include <map>
#include <vector>

#include "barretenberg/avm_fuzzer/fuzz_lib/control_flow.hpp"
#include "barretenberg/avm_fuzzer/fuzz_lib/instruction.hpp"
#include "barretenberg/vm2/common/opcodes.hpp"
#include "barretenberg/vm2/simulation/lib/serialization.hpp"

namespace {

using bb::avm2::WireOpCode;
using bb::avm2::fuzzer::InstructionBlock;

std::map<WireOpCode, size_t> count_opcodes(const std::vector<uint8_t>& bytecode)
{
    std::map<WireOpCode, size_t> counts;
    size_t pos = 0;
    while (pos < bytecode.size()) {
        auto instruction = bb::avm2::simulation::deserialize_instruction(bytecode, pos);
        counts[instruction.opcode]++;
        pos += instruction.size_in_bytes();
    }
    return counts;
}

size_t count_of(const std::map<WireOpCode, size_t>& counts, WireOpCode opcode)
{
    auto entry = counts.find(opcode);
    return entry == counts.end() ? 0 : entry->second;
}

InstructionBlock block_with(const FuzzInstruction& instruction)
{
    return InstructionBlock{ .instructions = { instruction } };
}

// Each instruction block is tagged with a distinct SET width so the decoded bytecode says which
// blocks made it in. The builder emits SET_32 for base offsets and pointers, and SET_16 for return
// sizes and jump conditions, so only the remaining widths work as markers.
SET_8_Instruction set_8_marker()
{
    return SET_8_Instruction{ .value_tag = bb::avm2::MemoryTag::U8,
                              .result_address = AddressRef{ .address = 10, .mode = AddressingMode::Direct },
                              .value = 1 };
}

SET_128_Instruction set_128_marker()
{
    return SET_128_Instruction{ .value_tag = bb::avm2::MemoryTag::U128,
                                .result_address = AddressRef{ .address = 11, .mode = AddressingMode::Direct },
                                .value_low = 1,
                                .value_high = 0 };
}

SET_64_Instruction set_64_marker()
{
    return SET_64_Instruction{ .value_tag = bb::avm2::MemoryTag::U64,
                               .result_address = AddressRef{ .address = 12, .mode = AddressingMode::Direct },
                               .value = 1 };
}

ReturnOptions default_return_options()
{
    return ReturnOptions{ .return_size = 1,
                          .return_value_tag = bb::avm2::MemoryTag::U8,
                          .return_value_offset_index = 0 };
}

// Terminating a block must hand generation back to a block that is still open, otherwise every
// later CFG instruction is silently dropped.
TEST(ControlFlowStructureTest, GenerationResumesInAnOpenBlockAfterATerminator)
{
    auto instruction_blocks = std::vector<InstructionBlock>{
        block_with(set_8_marker()),   // then branch
        block_with(set_128_marker()), // else branch
        block_with(set_64_marker()),  // appended after the then branch returns
    };

    auto control_flow = ControlFlow(instruction_blocks);
    control_flow.process_cfg_instruction(JumpIfToNewBlock{ .then_program_block_instruction_block_idx = 0,
                                                           .else_program_block_instruction_block_idx = 1,
                                                           .condition_offset_index = 0 });
    // Closes the then branch. The else branch is still open, so it must become current.
    control_flow.process_cfg_instruction(FinalizeWithReturn{ .return_options = default_return_options() });
    control_flow.process_cfg_instruction(SwitchToNonTerminatedBlock{ .non_terminated_block_idx = 0 });
    control_flow.process_cfg_instruction(InsertSimpleInstructionBlock{ .instruction_block_idx = 2 });

    auto counts = count_opcodes(control_flow.build_bytecode(default_return_options()));

    EXPECT_EQ(count_of(counts, WireOpCode::SET_8), 1);
    EXPECT_EQ(count_of(counts, WireOpCode::SET_128), 1);
    // The block appended after the terminator has to reach the bytecode.
    EXPECT_EQ(count_of(counts, WireOpCode::SET_64), 1);
}

// An INTERNALCALL appended to a block that already returned can never be reached, and would make an
// unreachable block current so that everything generated after it is dead as well.
TEST(ControlFlowStructureTest, InternalCallAfterATerminatorIsDropped)
{
    auto instruction_blocks = std::vector<InstructionBlock>{ block_with(set_64_marker()) };

    auto control_flow = ControlFlow(instruction_blocks);
    control_flow.process_cfg_instruction(FinalizeWithReturn{ .return_options = default_return_options() });
    control_flow.process_cfg_instruction(InsertInternalCall{ .target_program_block_instruction_block_idx = 0 });

    auto counts = count_opcodes(control_flow.build_bytecode(default_return_options()));

    EXPECT_EQ(count_of(counts, WireOpCode::INTERNALCALL), 0);
    EXPECT_EQ(count_of(counts, WireOpCode::SET_64), 0);
}

// The guard above must not stop an internal call from being emitted in an open block.
TEST(ControlFlowStructureTest, InternalCallInAnOpenBlockIsEmitted)
{
    auto instruction_blocks = std::vector<InstructionBlock>{
        block_with(set_8_marker()),
        block_with(set_64_marker()),
    };

    auto control_flow = ControlFlow(instruction_blocks);
    control_flow.process_cfg_instruction(InsertSimpleInstructionBlock{ .instruction_block_idx = 0 });
    control_flow.process_cfg_instruction(InsertInternalCall{ .target_program_block_instruction_block_idx = 1 });

    auto counts = count_opcodes(control_flow.build_bytecode(default_return_options()));

    EXPECT_EQ(count_of(counts, WireOpCode::INTERNALCALL), 1);
    EXPECT_EQ(count_of(counts, WireOpCode::SET_8), 1);
    EXPECT_EQ(count_of(counts, WireOpCode::SET_64), 1);
    EXPECT_EQ(count_of(counts, WireOpCode::INTERNALRETURN), 1);
}

// A run of CFG instructions that each close a block must keep consuming the open blocks the earlier
// ones created, rather than freezing after the first terminator.
TEST(ControlFlowStructureTest, EveryBranchOfNestedConditionalsIsPopulated)
{
    auto instruction_blocks = std::vector<InstructionBlock>{
        block_with(set_8_marker()),
        block_with(set_128_marker()),
        block_with(set_64_marker()),
    };

    auto control_flow = ControlFlow(instruction_blocks);
    control_flow.process_cfg_instruction(JumpIfToNewBlock{ .then_program_block_instruction_block_idx = 0,
                                                           .else_program_block_instruction_block_idx = 1,
                                                           .condition_offset_index = 0 });
    control_flow.process_cfg_instruction(FinalizeWithReturn{ .return_options = default_return_options() });
    control_flow.process_cfg_instruction(JumpIfToNewBlock{ .then_program_block_instruction_block_idx = 2,
                                                           .else_program_block_instruction_block_idx = 2,
                                                           .condition_offset_index = 0 });
    control_flow.process_cfg_instruction(FinalizeWithReturn{ .return_options = default_return_options() });
    control_flow.process_cfg_instruction(FinalizeWithReturn{ .return_options = default_return_options() });

    auto counts = count_opcodes(control_flow.build_bytecode(default_return_options()));

    EXPECT_EQ(count_of(counts, WireOpCode::SET_8), 1);
    EXPECT_EQ(count_of(counts, WireOpCode::SET_128), 1);
    // Both branches of the second conditional draw on block 2.
    EXPECT_EQ(count_of(counts, WireOpCode::SET_64), 2);
    EXPECT_EQ(count_of(counts, WireOpCode::JUMPI_32), 2);
}

} // namespace
